    def f(string, match, base=base):
        if string[0] == '-':
            sign = -1
        else:
            sign = 1

        # Only auto-detect base if no base was explicitly provided
        if base is None and len(string) > 1:
            if string[0] in '+-' and len(string) > 2:
                check_start = 1
            else:
                check_start = 0
            if string[check_start] == '0' and check_start + 1 < len(string):
                if string[check_start + 1] in 'bB':
                    base = 2
                elif string[check_start + 1] in 'oO':
                    base = 8
                elif string[check_start + 1] in 'xX':
                    base = 16
                else:
                    base = 10
            else:
                base = 10

